import React, { useState, useEffect, useRef } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import './PlayerDashboard.css';

const statConfig = {
    Strength: ['Saving Throw', 'Athletics'],
    Dexterity: ['Saving Throw', 'Acrobatics', 'Sleight of Hand', 'Stealth'],
    Constitution: ['Saving Throw'],
    Intelligence: ['Saving Throw', 'Arcana', 'History', 'Investigation', 'Nature', 'Religion'],
    Wisdom: ['Saving Throw', 'Animal Handling', 'Insight', 'Medicine', 'Perception', 'Survival'],
    Charisma: ['Saving Throw', 'Deception', 'Intimidation', 'Performance', 'Persuasion']
};

const calculateModifier = (score) => Math.floor((score - 10) / 2);

const PlayerDashboard = () => {
    const location = useLocation();
    const navigate = useNavigate();
    const logContainerRef = useRef(null);

    // --- PANEL STATE'LERİ ---
    const [isTopOpen, setIsTopOpen] = useState(true);
    const [isLeftOpen, setIsLeftOpen] = useState(true);
    const [isRightOpen, setIsRightOpen] = useState(true);

    const [character, setCharacter] = useState(location.state?.character || null);
    const [gameCode, setGameCode] = useState(location.state?.gameCode || 'UNKNOWN');
    const [logs, setLogs] = useState([{ id: 1, text: "Joined the session. Waiting for GM..." }]);
    const [selectedStat, setSelectedStat] = useState('Dexterity'); // Default selected stat

    useEffect(() => {
        if (!character) {
            navigate('/join-game');
        }
    }, [character, navigate]);

    useEffect(() => {
        if (isRightOpen && logContainerRef.current) {
            logContainerRef.current.scrollTop = logContainerRef.current.scrollHeight;
        }
    }, [logs, isRightOpen]);

    if (!character) return null;

    const profBonus = Math.ceil(character.level / 4) + 1;

    const handleStatChange = (field, value) => {
        setCharacter(prev => ({ ...prev, [field]: value }));
    };

    const toggleInspiration = () => {
        setCharacter(prev => ({ ...prev, inspiration: !prev.inspiration }));
    };

    const addLog = (text) => {
        setLogs(prev => [...prev, { id: Date.now(), text }]);
    };

    const rollDice = (name, bonus) => {
        const roll = Math.floor(Math.random() * 20) + 1;
        const total = roll + bonus;
        addLog(`Rolled ${name}: 1d20 (${roll}) ${bonus >= 0 ? '+' : ''}${bonus} = ${total}`);
        if (!isRightOpen) setIsRightOpen(true);
    };

    const getSkillBonusValue = (statName, skillName) => {
        const key = `${statName}-${skillName}`;
        const modifier = calculateModifier(character.stats[statName]);
        const isProficient = character.proficiencies && character.proficiencies[key];
        return modifier + (isProficient ? profBonus : 0);
    };

    return (
        <div className="player-dashboard-wrapper">

            {/* ================= LAYER 0: MAP / BOARD ================= */}
            <div className="layer-map">
                <div className="board-placeholder">
                    <h3>GAME BOARD</h3>
                    <p>Waiting for GM to share a map...</p>
                </div>
            </div>

            {/* ================= LAYER 3: ÜST MENÜ ================= */}
            <div className={`layer-top-menu ${isTopOpen ? 'open' : 'closed'}`}>
                <div className="top-menu-content">
                    <div className="top-left">
                        <button type="button" className="exit-btn" onClick={() => navigate('/main-menu')}>🚪 LEAVE</button>

                        <div className="pd-char-info">
                            <span className="pd-char-name">{character.name}</span>
                            <span className="pd-char-sub">Lvl {character.level} {character.charClass}</span>
                        </div>

                        <div className="pd-combat-stats">
                            <div className="pd-stat-box">
                                <label>AC</label>
                                <input type="number" value={character.armorClass} onChange={(e) => handleStatChange('armorClass', parseInt(e.target.value) || 0)} />
                            </div>
                            <div className="pd-stat-box">
                                <label>Speed</label>
                                <input type="number" value={character.speed} onChange={(e) => handleStatChange('speed', parseInt(e.target.value) || 0)} />
                            </div>
                            <div className="pd-stat-box hp-box">
                                <label>HP</label>
                                <div className="hp-inputs">
                                    <input type="number" value={character.currentHp} onChange={(e) => handleStatChange('currentHp', parseInt(e.target.value) || 0)} className="current-hp" />
                                    <span>/</span>
                                    <input type="number" value={character.maxHp} onChange={(e) => handleStatChange('maxHp', parseInt(e.target.value) || 0)} className="max-hp" />
                                </div>
                            </div>
                            <button 
                                className={`pd-inspiration-btn ${character.inspiration ? 'active' : ''}`}
                                onClick={toggleInspiration}
                                title="Toggle Inspiration"
                            >
                                {character.inspiration ? '🌟 INSP' : '⭐ INSP'}
                            </button>
                        </div>
                    </div>
                </div>
                <div className="menu-handle top-handle" onClick={() => setIsTopOpen(!isTopOpen)}>
                    {isTopOpen ? '▲' : '▼'}
                </div>
            </div>

            {/* ================= LAYER 2: SOL MENÜ (Stats & Skills) ================= */}
            <div className={`layer-sidebar left-sidebar ${isLeftOpen ? 'open' : 'closed'}`}>
                <div className="left-handle" onClick={() => setIsLeftOpen(!isLeftOpen)}>
                    {isLeftOpen ? '◀' : '▶'}
                </div>
                <div className="sidebar-content">
                    <div className="pd-attributes-grid">
                        {Object.keys(statConfig).map(stat => {
                            const mod = calculateModifier(character.stats[stat]);
                            return (
                                <div 
                                    key={stat} 
                                    className={`pd-attr-btn ${selectedStat === stat ? 'selected' : ''}`}
                                    onClick={() => setSelectedStat(stat)}
                                >
                                    <span className="attr-name">{stat.substring(0, 3).toUpperCase()}</span>
                                    <span className="attr-val">{character.stats[stat]}</span>
                                    <span className="attr-mod">{mod >= 0 ? `+${mod}` : mod}</span>
                                </div>
                            );
                        })}
                    </div>

                    <div className="pd-skills-header">
                        <h2>{selectedStat}</h2>
                        <button 
                            className="roll-stat-btn"
                            onClick={() => rollDice(`${selectedStat} Check`, calculateModifier(character.stats[selectedStat]))}
                        >
                            ROLL {selectedStat.toUpperCase()}
                        </button>
                    </div>

                    <div className="pd-skills-list">
                        {statConfig[selectedStat].map(skill => {
                            const bonus = getSkillBonusValue(selectedStat, skill);
                            const isProficient = character.proficiencies && character.proficiencies[`${selectedStat}-${skill}`];
                            return (
                                <div 
                                    key={skill} 
                                    className={`pd-skill-row ${isProficient ? 'proficient' : ''}`}
                                    onClick={() => rollDice(skill, bonus)}
                                >
                                    <div className={`pd-prof-dot ${isProficient ? 'active' : ''}`}></div>
                                    <span className="pd-skill-name">{skill}</span>
                                    <span className="pd-skill-bonus">{bonus >= 0 ? `+${bonus}` : bonus}</span>
                                </div>
                            );
                        })}
                    </div>
                </div>
            </div>

            {/* ================= LAYER 2: SAĞ MENÜ (Logs & Dice) ================= */}
            <div className={`layer-sidebar right-sidebar ${isRightOpen ? 'open' : 'closed'}`}>
                <div className="right-handle" onClick={() => setIsRightOpen(!isRightOpen)}>
                    {isRightOpen ? '▶' : '◀'}
                </div>
                <div className="sidebar-content">
                    <div className="pd-log-header">
                        <h3>DICE & LOGS</h3>
                        <span className="pd-game-code">CODE: {gameCode}</span>
                    </div>
                    <div className="pd-log-container" ref={logContainerRef}>
                        {logs.map(log => (
                            <div key={log.id} className="pd-log-entry">
                                <span className="log-time">[{new Date(log.id).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}]</span>
                                <span className="log-text">{log.text}</span>
                            </div>
                        ))}
                    </div>
                </div>
            </div>

        </div>
    );
};

export default PlayerDashboard;
